"""Audit the actual original C1 refresh and adopt only its three generated bytes.

This is a hosted transport adapter for the retained C1 intake/adopter, not a
new generator or another Go invocation. The resulting one-parent delta bundle
is reviewed independently before publication; this worker has contents:read.
"""
from pathlib import Path
import collections
import hashlib
import importlib.util
import json
import os
import re
import stat
import sys
import time

P = Path(__file__).resolve().parent
RUN_SHA256 = "58480e043a97c23997e65f1c5f9c5a1246c5899fb77e8d557621d2e8f6e04b9f"
if hashlib.sha256((P/"run.py").read_bytes()).hexdigest() != RUN_SHA256:
    raise SystemExit("C1_ORIGINAL_EXECUTION_ADAPTER_CHANGED")
spec = importlib.util.spec_from_file_location("canonical_c1_hosted_protocol", P/"run.py")
protocol = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = protocol
spec.loader.exec_module(protocol)
fixed = protocol.fixed
HEAD, TREE, BRANCH = protocol.HEAD, protocol.TREE, protocol.BRANCH
GENERATED = protocol.GENERATED

def verify_bundle(owner, bundle, commit):
    """A delta bundle carries one new head and requires the exact producer parent."""
    reference = "refs/heads/"+protocol.BRANCH
    owner.git("bundle", "verify", str(bundle))
    fixed.require(owner.git("bundle", "list-heads", str(bundle)).decode().strip().split() == [commit, reference],
                  "ONE_EXACT_BUNDLE_HEAD")
    data = owner.read(bundle)
    header = data.split(b"\n\n", 1)[0].decode("utf-8")
    prerequisites = [line[1:].split(" ", 1)[0] for line in header.splitlines() if line.startswith("-")]
    fixed.require(prerequisites == [protocol.HEAD] and 0 < len(data) <= 32*1024*1024,
                  "EXACT_SMALL_PREREQUISITE_BUNDLE")
    return {"path": bundle.name, "bytes": len(data), "sha256": fixed.sha(data),
            "prerequisite": protocol.HEAD, "head": commit, "ref": reference}



def semantic_products(owner, need):
    """Exact retained independent C1 product-semantic block; no generation."""
    E, W, J, rawpins = fixed.EVIDENCE/"execution", fixed.WORKTREE, HEAD, protocol.RAW_PINS
    read, sha = owner.read, fixed.sha
    def parsed(path):
        return json.loads(read(path))
    for rel,digest in rawpins.items():need(sha(read(W/rel))==digest,'raw C0 exact '+rel)
    raw=parsed(W/'docs/apple-runtime/p10/p10-505-execution-evidence.json');rawrows={r['name']:r for r in raw['entries']}
    receipt=parsed(E/'products/action-contract-execution.json');report=parsed(E/'products/action-contract-coverage.json')
    rows=report['entries'];names=[r['callable'] for r in rows]
    need(len(rows)==505 and len(rawrows)==505 and names==sorted(rawrows) and len(set(names))==505,'exact505 membership/order')
    need(receipt['sourceSha']==report['sourceSha']==J and receipt['sourceFingerprint']==report['sourceFingerprint'],'actual J producer/fingerprint')
    need(receipt['executionEvidenceSha256']==report['executionEvidenceSha256']==rawpins['docs/apple-runtime/p10/p10-505-execution-evidence.json'],'raw execution byte join')
    need(receipt['command']==['go','test','-count=1','-timeout=20m','-run','^TestP10_VerifyAndRecord505CatalogExecution$','-v','.'] and receipt['exitCode']==0,'original child command')
    need(receipt['localLog']=='dist/p10r15/catalog-contract-execution.log' and receipt['localLogSha256']==sha(read(E/'products/catalog-contract-execution.log')),'actual child log retained')
    dims=('legacyNamedCompile','v2NamedCompile','nativeIdentifier','parameterContract','decompile','structuralRoundtrip','nativeSpecimen','losslessImport','hybridImport','editIsolation','signedEditor','signedRuntime','physicalIPad','installedProvider')
    for row in rows:
     rr=rawrows[row['callable']]
     need(set(row['dimensions'])==set(dims),'closed dimensions '+row['callable'])
     need(row['nativeIdentifier']==rr.get('shortcutIdentifier','') and row['emittedKeysSample']==rr.get('emittedKeysSample',[]),'raw wire join '+row['callable'])
     need(all(row['dimensions'][key]=='PASS' for key in dims[:6]),'six synthetic dimensions '+row['callable'])
     need(row['dimensions']['nativeSpecimen']==rr.get('nativeSpecimenParityStatus','NO_NATIVE_SPECIMEN') and
          all(row['dimensions'][key]=='NOT_SAMPLED_PER_CALLABLE' for key in dims[7:12]) and
          row['dimensions']['physicalIPad']=='BLOCKED_DEVICE' and row['dimensions']['installedProvider']=='NOT_CHECKED','independent native boundaries '+row['callable'])
     need(row['syntheticSourceHashes']=={dialect:sha(rr.get(dialect+'Source','').encode()) for dialect in ('legacy','v2')},'actual synthetic source hashes '+row['callable'])
     need((row['kind']=='COMPILER_CONSTRUCT')==bool(rr.get('compilerConstruct')),'construct separation '+row['callable'])
     need(row['evidenceTier']=='STRUCTURAL_NATIVE_SYNTHETIC' and row['status']==('COMPILER_CONSTRUCT' if row['kind']=='COMPILER_CONSTRUCT' else 'PARTIALLY_VERIFIED'),'bounded status '+row['callable'])
    summary=report['summary']
    need(summary['callableEntries']==497 and summary['compilerConstructs']==8 and summary['uniqueCallableNativeIdentifiers']==382,'497/8/382 denominators')
    need(summary['dimensions']=={key:dict(collections.Counter(r['dimensions'][key] for r in rows)) for key in dims},'all aggregate dimensions derived')
    md=read(E/'products/action-contract-coverage.md').decode()
    observed=[line for line in md.splitlines() if line.startswith('| ')][1:]
    expected=['| '+' | '.join([r['callable'],r['nativeIdentifier'],r['dimensions']['legacyNamedCompile'],r['dimensions']['v2NamedCompile'],r['dimensions']['structuralRoundtrip'],r['dimensions']['nativeSpecimen'],r['status']])+' |' for r in rows]
    need(observed==expected,'independent exact Markdown projection')
    return {"entries": len(rows), "summary": summary, "source": J,
            "products": {path: {"bytes": len(read(E/"products"/Path(path).name)),
                        "sha256": sha(read(E/"products"/Path(path).name))} for path in GENERATED}}


def execution_receipts(owner):
    output = fixed.EVIDENCE/"execution"
    checks = []
    def need(condition, name):
        checks.append({"check": name, "passed": bool(condition)})
        fixed.require(condition, name)
    def parsed(path):
        return json.loads(owner.read(path))
    raw = owner.read(output/"result.original.json")
    result = json.loads(raw)
    need(result["status"] == "PASS" and result["failures"] == [] and
         result["source"] == HEAD and result["tree"] == TREE and
         result["sourceRole"] == "canonical-precursor" and
         result["controllerSource"] == fixed.CONTEXT["controllerSha"], "EXACT_C1_PRODUCER_AND_CONTROLLER")
    need(result["sourceClosureUnchanged"] is True and result["controllerUnchanged"] is True and
         result["dependenciesUnchanged"] is True and result["nativeAcceptance"] is False and
         result["global179Acceptance"] is False and result["wholeOwnerSeconds"] == 1740 and
         0 < result["elapsedSeconds"] < 1740, "ORIGINAL_C1_BOUNDS_SCOPE_AND_GUARDS")
    need(result["originalOracleOwnerSHA256"] == fixed.ORIGINAL_C1_OWNER_SHA256 and
         result["originalC0HandoffSHA256"] == fixed.C0_HANDOFF_SHA256 and
         result["ownerSHA256"] == RUN_SHA256 == fixed.sha(owner.read(output/"run.py")) and
         result["sharedControllerSHA256"] == protocol.SHARED_SHA256 ==
         fixed.sha(owner.read(output/"hosted_source.py")) == fixed.sha(owner.read(P/"hosted_source.py")) and
         result["helperSHA256"] == fixed.HELPER_SHA256 == fixed.sha(owner.read(output/"owned_source_process.py")),
         "C1_EXACT_EXECUTED_OWNER_BYTES")
    before, after = [parsed(output/name) for name in ("source-before.original.json", "source-after.original.json")]
    protocol.validate_post_state(before, after)
    need((before["head"], before["tree"], before["branch"], before["status"]) == (HEAD, TREE, BRANCH, "") and
         protocol.snapshot_after(owner, before) == after, "C1_ACTUAL_CURRENT_SOURCE_JOIN")
    need(sorted(after["status"].splitlines()) == sorted(" M "+path for path in GENERATED) and
         result["declaredGeneratedPaths"] == list(GENERATED), "C1_EXACT_THREE_GENERATED_PATHS")
    dependencies = [parsed(output/name) for name in ("dependency-before.original.json", "dependency-after.original.json")]
    fingerprints = [parsed(output/name) for name in ("c1-fingerprint-before.original.json", "c1-fingerprint-after.original.json")]
    need(dependencies[0] == dependencies[1] == json.loads(json.dumps(owner.dependencies(), allow_nan=False)) and
         fingerprints[0] == fingerprints[1] == json.loads(json.dumps(protocol.c1_fingerprint(owner), allow_nan=False)),
         "C1_ORIGINAL_AND_CURRENT_DEPENDENCY_CLOSURE")
    controllers = [parsed(output/name) for name in ("controller-before.original.json", "controller-after.original.json")]
    need(controllers[0] == controllers[1] and controllers[0]["head"] == fixed.CONTEXT["controllerSha"],
         "C1_EXACT_CONTROLLER_CLOSURE")
    selected = parsed(output/"selection.original.json")
    need(selected["source"] == HEAD and selected["tree"] == TREE and selected["branch"] == BRANCH and
         selected["command"] == protocol.COMMAND and selected["producerSeconds"] == 1500 and
         selected["wholeOwnerSeconds"] == 1740 and selected["canonicalChildSeconds"] == [1260, 120, 120] and
         selected["canonicalGoTimeout"] == "20m" and selected["rawPins"] == protocol.RAW_PINS and
         selected["generatedPaths"] == list(GENERATED) and
         selected["controllerSha"] == fixed.CONTEXT["controllerSha"] and
         selected["originalC0HandoffSHA256"] == fixed.C0_HANDOFF_SHA256, "C1_ORIGINAL_CLOSED_SELECTION")
    for path, digest in {protocol.GENERATOR: protocol.GENERATOR_SHA256,
                         protocol.CATALOG_GENERATOR: protocol.CATALOG_GENERATOR_SHA256,
                         protocol.TEST_FILE: protocol.TEST_FILE_SHA256, **protocol.RAW_PINS}.items():
        need(before["trackedPhysicalInputs"][path]["sha256"] == after["trackedPhysicalInputs"][path]["sha256"] ==
             fixed.sha(owner.read(fixed.WORKTREE/path)) == digest, "C1_EXACT_INPUT:"+path)
    preflight = parsed(output/"preflight.original.json")
    need(preflight["admitted"] is True and preflight["admission"] == fixed.ADMISSION_FLOORS and
         preflight["liveFloor"] == fixed.LIVE_FLOORS and
         all(preflight["free"][key] >= floor for key, floor in fixed.ADMISSION_FLOORS.items()) and
         all(result["minimumFree"][key] >= floor for key, floor in fixed.LIVE_FLOORS.items()),
         "C1_UNCHANGED_CAPACITY_POLICY")
    processes = []
    for path in sorted((output/"commands").glob("*.process.original.json")):
        process = parsed(path)
        name = process["name"]
        need(re.fullmatch(r"[0-9]{3}-[a-z0-9-]+", name) is not None and path.name == name+".process.original.json",
             "C1_ACTUAL_PROCESS_IDENTITY")
        need(process["status"] == "PASS" and process["exitCode"] == 0 and process["error"] is None and
             process["timedOut"] is False and process["cancelled"] is False and process["cancelSignal"] is None and
             process["wholeDeadlineExceeded"] is False, "C1_ORIGINAL_PROCESS_SUCCESS:"+name)
        cleanup = process["cleanup"]
        need(process["pid"] == process["pgid"] == process["sid"] and cleanup["parentReaped"] is True and
             cleanup["noLiveGroupMembers"] is True and cleanup["errors"] == [] and
             cleanup["after"]["state"] in ("ABSENT", "ZOMBIE_ONLY") and cleanup["after"]["live"] is False,
             "C1_ORIGINAL_PROCESS_CLEANUP:"+name)
        for channel in ("stdout", "stderr"):
            data = owner.read(output/"commands"/(name+"."+channel+".original"))
            need(process[channel] == {"complete": True, "sha256": fixed.sha(data), "bytes": len(data)},
                 "C1_COMPLETE_ORIGINAL_STREAM:"+name+":"+channel)
        processes.append(process)
    required = result["processes"]
    need(len(required) == 1 and required[0] in processes and required[0]["argv"] == protocol.COMMAND and
         required[0]["commandSeconds"] == 1500 and required[0]["wholeOwnerSeconds"] == 1740 and
         required[0]["cleanup"]["after"]["state"] == "ABSENT", "C1_ONE_ORIGINAL_1500_SECOND_PRODUCER")
    observers = [row for row in processes if row["name"].endswith("-concurrent-owner")]
    need(len(observers) == 1 and fixed.sha(owner.read(output/"admission-observer.original.py")) == fixed.OBSERVER_SHA256,
         "C1_ONE_EXACT_ROOT_OBSERVER")
    observer = parsed(output/"commands"/(observers[0]["name"]+".stdout.original"))
    need(observer["admitted"] is True and observer["blockedPids"] == observer["errors"] == [] and
         observer["observerUid"] == 0 and observer["policy"] == "new-conservative-all-live-go-20261126",
         "C1_EXCLUSIVE_OWNER_ADMISSION")
    prerequisite = owner.read(output/"prerequisite-result.original.json")
    prep = json.loads(prerequisite)
    need(prerequisite == owner.read(fixed.EVIDENCE/"prerequisite/result.original.json") and
         prep["status"] == "PASS" and prep["source"] == HEAD and prep["tree"] == TREE and
         prep["controllerSha"] == fixed.CONTEXT["controllerSha"] and prep["sourceUnchanged"] is True and
         prep["controllerUnchanged"] is True, "C1_EXACT_PREREQUISITE_JOIN")
    original_stdout = owner.read(output/"commands"/(required[0]["name"]+".stdout.original"))
    revalidated = protocol.verify_products(owner, fingerprints[0]["fingerprint"], original_stdout)
    for path, pin in result["products"]["products"].items():
        need(path in (*GENERATED, protocol.LOCAL_LOG), "C1_CLOSED_PRODUCT_PATH")
        data = owner.read(output/"products"/Path(path).name)
        need(data == owner.read(fixed.WORKTREE/path) and fixed.sha(data) == pin["sha256"] and
             len(data) == pin["bytes"] and
             {key: revalidated["products"][path][key] for key in ("bytes", "sha256")} ==
             {key: pin[key] for key in ("bytes", "sha256")}, "C1_RETAINED_ACTUAL_PRODUCT:"+path)
    need(set(result["products"]["products"]) == set((*GENERATED, protocol.LOCAL_LOG)) and
         result["products"]["canonicalStdout"] == revalidated["canonicalStdout"] and
         result["products"]["actualRun"] == revalidated["actualRun"] and
         result["products"]["actualPass"] == revalidated["actualPass"], "C1_ORIGINAL_PRODUCT_VALIDATION_JOIN")
    semantics = semantic_products(owner, need)
    return {"schema": "cherri-canonical-c1-hosted-intake/1", "status": "PASS", "source": HEAD, "tree": TREE,
            "controllerSha": fixed.CONTEXT["controllerSha"], "ownerResultSHA256": fixed.sha(raw),
            "originalOracleIntakeSHA256": fixed.ORIGINAL_C1_INTAKE_SHA256,
            "originalC0HandoffSHA256": fixed.C0_HANDOFF_SHA256,
            "checkCount": len(checks), "checks": checks, "semantics": semantics,
            "products": semantics["products"],
            "actualCleanupStates": {row["name"]: row["cleanup"]["after"]["state"] for row in processes},
            "goRepeated": False, "producerReplayed": False, "nativeAcceptance": False, "global179Acceptance": False}


def main():
    fixed.require(len(sys.argv) == 1, "FIXED_C1_ADOPTION_ROUTE")
    with fixed.owned.WholeBudget(240, cleanup_seconds=8, final_reserve=20) as budget:
        output = fixed.EVIDENCE/"adoption"
        output.mkdir(mode=0o700)
        owner = fixed.SourceOwner({"worktree": str(fixed.WORKTREE)}, output, budget)
        failures, commit, tree, bundle_pin = [], None, None, None
        controller_before = controller_after = before = after = observed = intake = None
        c1_before = c2_before = c1_after = c2_after = None
        fixed.owned.original(output/"hosted-runtime.original.json", fixed.runtime_identity())
        fixed.owned.original(output/"adopt.py", owner.read(P/"adopt.py"))
        try:
            controller_before = fixed.controller_snapshot(owner)
            fixed.owned.original(output/"controller-before.original.json", controller_before)
            before = json.loads(owner.read(fixed.EVIDENCE/"execution/source-before.original.json"))
            observed = protocol.snapshot_after(owner, before)
            fixed.require(observed == json.loads(owner.read(fixed.EVIDENCE/"execution/source-after.original.json")),
                          "POST_PRODUCER_SOURCE_DRIFT")
            fixed.owned.original(output/"source-before.original.json", observed)
            fixed.require(sorted(observed["status"].splitlines()) == sorted(" M "+path for path in GENERATED),
                          "EXACT_THREE_C1_DIRTY_PRODUCTS")
            _, observed_owner, errors = owner.observe_concurrent_owner()
            decision = json.loads(owner.read(observed_owner))
            fixed.require(not owner.read(errors) and decision["admitted"] is True and decision["blockedPids"] == [],
                          "C1_ADOPTION_EXCLUSIVE_OWNER_ADMISSION")
            resources = fixed.free()
            fixed.owned.original(output/"capacity.original.json", {"observed": resources,
                "admission": fixed.ADMISSION_FLOORS, "live": fixed.LIVE_FLOORS})
            fixed.require(all(resources[key] >= floor for key, floor in fixed.ADMISSION_FLOORS.items()),
                          "C1_ADOPTION_CAPACITY_ADMISSION")
            remote = owner.git("-c", "credential.helper=", "ls-remote", "--heads", "origin", "refs/heads/"+BRANCH)
            fixed.require(remote.decode().strip().split() == [HEAD, "refs/heads/"+BRANCH], "UNCHANGED_PUBLISHED_C1_PRODUCER")
            fixed.owned.original(output/"producer-ref.original.txt", remote)
            intake = execution_receipts(owner)
            fixed.owned.original(output/"intake.original.json", intake)
            for path in GENERATED:
                raw = owner.read(fixed.WORKTREE/path)
                pin = intake["products"][path]
                fixed.require(fixed.sha(raw) == pin["sha256"] and len(raw) == pin["bytes"] and
                              raw == owner.read(fixed.EVIDENCE/"execution/products"/Path(path).name),
                              "C1_BYTE_IDENTICAL_ORIGINAL_ADOPTION")
            c1_before, c2_before = protocol.c1_fingerprint(owner), owner.dependencies()
            fixed.owned.original(output/"fingerprints-before.original.json", {"c1": c1_before, "c2": c2_before})
            paths = sorted(GENERATED)
            owner.git("diff", "--check", "--", *paths)
            owner.git("add", "--", *paths)
            fixed.require(sorted(owner.git("diff", "--cached", "--name-only").decode().splitlines()) == paths,
                          "ONLY_THREE_C1_STAGED_PATHS")
            owner.git("-c", "gc.auto=0", "-c", "maintenance.auto=false", "-c", "user.name=Cherri Completion Agent",
                      "-c", "user.email=cherri-completion@users.noreply.github.com", "commit", "-m",
                      "chore: adopt original source-bound canonical C1 contracts [skip ci]")
            commit, tree = (owner.git("rev-parse", argument).decode().strip() for argument in ("HEAD", "HEAD^{tree}"))
            fixed.require(owner.git("rev-parse", "HEAD^").decode().strip() == HEAD and
                          sorted(owner.git("diff-tree", "--no-commit-id", "--name-only", "-r", "HEAD").decode().splitlines()) ==
                          paths, "EXACT_C1_PARENT_AND_THREE_PRODUCTS")
            after = owner.snapshot()
            fixed.owned.original(output/"source-after.original.json", after)
            fixed.require((after["head"], after["tree"], after["branch"], after["status"]) ==
                          (commit, tree, BRANCH, "") and after["trackedPhysicalInputs"] == observed["trackedPhysicalInputs"],
                          "C1_COMMITTED_PHYSICAL_BYTES_UNCHANGED")
            c1_after, c2_after = protocol.c1_fingerprint(owner), owner.dependencies()
            fixed.require(c1_before == c1_after and c2_before == c2_after, "C1_ADOPTION_DEPENDENCIES_CHANGED")
            fixed.owned.original(output/"fingerprints-after.original.json", {"c1": c1_after, "c2": c2_after})
            bundle = output/"canonical-c1.original.bundle"
            owner.git("bundle", "create", str(bundle), "refs/heads/"+BRANCH, "^"+HEAD)
            bundle_pin = verify_bundle(owner, bundle, commit)
            fixed.owned.original(output/"bundle.original.json", bundle_pin)
        except BaseException as error:
            failures.append({"stage": "adoption", "type": type(error).__name__, "message": str(error)})
        finally:
            with budget.finalizing():
                try:
                    controller_after = fixed.controller_snapshot(owner)
                    fixed.owned.original(output/"controller-after.original.json", controller_after)
                    fixed.require(controller_before == controller_after, "C1_ADOPTION_CONTROLLER_CHANGED")
                    final = owner.snapshot(finalizing=True) if commit is not None else protocol.snapshot_after(owner, before)
                    fixed.owned.original(output/"source-final.original.json", final)
                    if after is not None:
                        fixed.require(final == after, "C1_POST_BUNDLE_SOURCE_CHANGED")
                except BaseException as error:
                    failures.append({"stage": "post-source", "type": type(error).__name__, "message": str(error)})
                if budget.cancel_signal is not None or time.monotonic() >= budget.deadline:
                    failures.append({"stage": "owner", "type": "CANCELLED_OR_DEADLINE", "signal": budget.cancel_signal})
                passed = not failures and bundle_pin is not None
                report = {"schema": "cherri-canonical-c1-hosted-byte-adoption/1", "status": "PASS" if passed else "FAIL",
                    "producerSource": HEAD, "producerTree": TREE, "controllerSha": fixed.CONTEXT["controllerSha"],
                    "ownerResultSHA256": intake["ownerResultSHA256"] if intake else None,
                    "originalOracleAdoptionSHA256": fixed.ORIGINAL_C1_ADOPTION_SHA256,
                    "originalC0HandoffSHA256": fixed.C0_HANDOFF_SHA256,
                    "commit": commit, "tree": tree, "branch": BRANCH, "bundle": bundle_pin,
                    "changedTrackedPaths": list(GENERATED), "wholeOwnerSeconds": 240,
                    "elapsedSeconds": time.monotonic()-budget.started, "minimumFree": owner.minimum,
                    "failures": failures, "goExecuted": False, "remotePushExecuted": False,
                    "nativeAcceptance": False, "global179Acceptance": False}
                with budget.defer():
                    pin = fixed.owned.original(output/"result.original.json", report)
    print(json.dumps({"path": str(output/"result.original.json"), "sha256": pin["sha256"],
                      "status": report["status"], "commit": commit}), flush=True)
    return 0 if passed else 1


if __name__ == "__main__":
    raise SystemExit(main())
